/* ---- Layout shared with BNS SI Dynamic V2 ---- */
/* PDF header page only (Frappe copies the header into .wrapper): pull it to ~4mm from
   the top and cancel its 5mm bottom padding. */
.wrapper > .print-heading {
    margin-top:-11mm;
    margin-bottom:-5mm;
}
/* PDF footer page: Frappe pads it 15mm on top; -8mm puts the footer ~5mm from the
   page edge without shrinking the page body. */
.wrapper > .page-footer-1 {
    margin-top:-8mm;
}
.page-footer-1 {
    border-top: 1px solid black;
    padding-top: 1mm;
}
/* Browser preview and browser printing: 5mm page margins (also the screen padding). */
@page {
  margin: 5mm;
}
.bns-logo img {
  max-width: 100%;
  max-height: 30mm;
}
.print-heading h3 {
  font-size: 1.35em;
}
.bns-doc-title {
  margin: 0;
  font-size: 1.45em;
  white-space: nowrap;
}
.bns-doc-status {
  font-size: 0.85em;
  font-weight: bold;
  margin-bottom: 0.5mm;
}
.bns-inv-id {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse;
  margin-top: 1mm !important;
}
.bns-inv-id td {
  border: 1px solid #000 !important;
  padding: 1mm 1.5mm !important;
  text-align: left;
  vertical-align: top;
  white-space: nowrap;
  background: #fff;
}
.bns-inv-label {
  font-size: 7pt;
  font-weight: normal;
  color: #333;
}
.bns-inv-value {
  font-size: 9.5pt;
  font-weight: bold;
  line-height: 1.2;
}
/* Compact party block. */
.party-details-table p {
  margin: 0;
}
.party-details-table td {
  padding: 2px 4px !important;
}
/* Item rows never split; the item header repeats on every page. Only the item table:
   on the totals table (T&C cell spans rows) it would pad rows near a page cut. */
.bns-items tr {
  page-break-inside: avoid;
}
.bns-items thead {
  display: table-header-group;
}
/* Closing block: totals, HSN, bank, signatories; kept whole at the page foot. */
/* The item table sits in a floated col-xs-12; clear it so the block (and its
   measuring markers) start below the items. The gap is padding so it measures the
   same in the measuring pass and the real render. */
.final-tax-total-table {
  clear: both;
  padding-top: 2mm;  /* padding, not margin: a margin collapses into the clearance */
  width: 100%;
}
.final-tax-total-table > table,
.final-tax-total-table > div {
  page-break-inside: avoid;
}
.final-tax-total-table.bns-keep {
  page-break-inside: avoid;
}
.final-tax-total-table p {
  margin: 0;
}
.final-tax-total-table .bns-terms {
  text-align: left !important;
}
.final-tax-total-table .bns-terms ol,
.final-tax-total-table .bns-terms ul {
  margin: 0;
  padding-left: 5mm;
}
.final-tax-total-table .bns-terms li {
  line-height: 1.3;
}
.payment_terms_table th,
.payment_terms_table td {
  padding: 2px 4px !important;
}
/* Tally-style fill: empty rows continue the item columns down to the closing block. */
.bns-items tr.bns-fill td {
  background-color: #fff !important;
  border-top: 0 !important;
}
/* Measuring-pass markers (never printed in the final PDF). */
.bns-mk {
  height: 0;
  overflow: visible;
  font-size: 4pt;
  line-height: 1;
  white-space: nowrap;
}
.bns-ruler {
  height: 3pt;
  font-size: 2pt;
  line-height: 3pt;
  overflow: hidden;
}

/* Item cell, same as the Sales Invoice: name, then HSN/SAC and EAN in small italics. */
.item-det .item-det-item-name {
  text-align: left !important;
  padding-left: 1mm !important;
}
.item-det .item-det-item-name b {
  font-size: 1em;
}
.bns-item-sub {
  font-size: 0.8em;
  margin: 0;
}

/* Item table: one size across all BNS formats (a little bigger than before). */
.item-det td, .item-det th,
.item-det .item-det-item-name {
  font-size: 8.5pt !important;
}
